validator:
function validate(input) {
  const [{ TVProgram = [], Content = [] }] = input;
  const contents = new Set(), slots = new Set();
  for (const [id, title, kids, type] of Content) {
    if (id === null || title === null || kids === null || type === null) return 'Content values cannot be null.';
    if (contents.has(String(Number(id)))) return `content_id ${id} appears twice in Content.`;
    if (!/^\d+$/.test(id)) return `content_id ${id} must be a whole number.`;
    contents.add(String(Number(id)));
    if (kids !== 'Y' && kids !== 'N') return `Kids_content must be Y or N, not ${kids}.`;
  }
  for (const [date, id, channel] of TVProgram) {
    if (date === null || id === null || channel === null) return 'TVProgram values cannot be null.';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `program_date ${date} is not YYYY-MM-DD.`;
    const key = `${date}|${id}`;
    if (slots.has(key)) return `(program_date, content_id) (${date}, ${id}) appears twice.`;
    slots.add(key);
    if (!contents.has(String(id))) return `content_id ${id} is not in Content.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const small = size === 'small';
  const titles = ['Aladdin', 'Cinderella', 'Frozen', 'Moana', 'Leetcode Movie', 'Database Sols', 'Alg. for Kids', 'Up'];
  const types = ['Movies', 'Movies', 'Series', 'Documentary'];
  const channels = ['LC-Channel', 'Disney Ch', 'Kids TV'];
  const contentCount = small ? pick(7) : 500;
  const Content = [], TVProgram = [];
  for (let id = 1; id <= contentCount; id++) {
    const title = small ? titles[pick(titles.length)] : `${titles[pick(titles.length)]} ${1 + pick(150)}`;
    Content.push([String(id), title, rand() < 0.6 ? 'Y' : 'N', types[pick(types.length)]]);
  }
  const day = k => new Date(Date.UTC(2019, 0, 1) + k * 86400000).toISOString().slice(0, 10);
  const smallDates = ['2020-05-31', '2020-06-01', '2020-06-15', '2020-06-15', '2020-06-30', '2020-07-01', '2019-06-10', '2021-06-10'];
  const slots = new Set(), target = contentCount === 0 ? 0 : small ? pick(9) : 2000;
  for (let tries = 0; TVProgram.length < target && tries < target * 4; tries++) {
    const date = small ? smallDates[pick(smallDates.length)] : rand() < 0.4 ? day(517 + pick(30)) : day(pick(1095));
    const id = 1 + pick(contentCount), key = `${date}|${id}`;
    if (slots.has(key)) continue;
    slots.add(key);
    TVProgram.push([date, id, channels[pick(channels.length)]]);
  }
  return [{ TVProgram, Content }];
}
